/* Palette: #1e1e2f (bg), #2a2a40 (card), #e0e0ff (text), #6c63ff (accent), #ff6584 (danger) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #1e1e2f;
  color: #e0e0ff;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 1rem;
}

.card {
  background: #2a2a40;
  border-radius: 1rem;
  padding: 1.5rem;
  max-width: 40rem;
  width: 100%;
  margin-top: 2rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
  color: #ffffff;
}

.subtitle {
  font-size: 1rem;
  margin-bottom: 1.5rem;
  color: #b0b0d0;
}

.course-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 2rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.form-row {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.form-row .form-group {
  flex: 1 1 8rem;
}

label {
  font-weight: 600;
  font-size: 0.95rem;
  color: #c0c0e0;
}

input,
select {
  font: inherit;
  padding: 0.5rem 0.75rem;
  border: 2px solid #3a3a55;
  border-radius: 0.5rem;
  background: #1e1e2f;
  color: #e0e0ff;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus,
select:focus {
  outline: none;
  border-color: #6c63ff;
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.3);
}

input:hover,
select:hover {
  border-color: #5a5a7a;
}

.btn-add {
  font: inherit;
  font-weight: 700;
  padding: 0.75rem 1.5rem;
  background: #6c63ff;
  color: #ffffff;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  align-self: flex-start;
}

.btn-add:hover {
  background: #5a52e0;
}

.btn-add:focus-visible {
  outline: 3px solid #ff6584;
  outline-offset: 2px;
}

.btn-add:active {
  transform: scale(0.97);
  background: #4a42c0;
}

.course-list-section {
  margin-bottom: 1.5rem;
}

h2 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
  color: #ffffff;
}

.course-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.course-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.5rem 0.75rem;
  background: #1e1e2f;
  border-radius: 0.5rem;
  border-left: 4px solid #6c63ff;
  word-break: break-word;
}

.course-name {
  font-weight: 600;
  flex: 1 1 auto;
  margin-right: 0.5rem;
}

.course-details {
  font-size: 0.9rem;
  color: #b0b0d0;
  white-space: nowrap;
}

.empty-message {
  color: #8888aa;
  font-style: italic;
}

.gpa-display {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 1rem;
  background: #1e1e2f;
  border-radius: 0.75rem;
  border: 2px solid #6c63ff;
}

.gpa-label {
  font-size: 1.1rem;
  font-weight: 600;
}

.gpa-value {
  font-size: 2rem;
  font-weight: 800;
  color: #6c63ff;
}

/* Responsive adjustments for 360px */
@media (max-width: 400px) {
  .card {
    padding: 1rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .form-row {
    flex-direction: column;
    gap: 0.75rem;
  }
  .gpa-value {
    font-size: 1.75rem;
  }
}

const courses = [];

const gradePoints = {
  A: 4.0,
  B: 3.0,
  C: 2.0,
  D: 1.0,
  F: 0.0
};

const form = document.getElementById('course-form');
const nameInput = document.getElementById('course-name');
const creditsInput = document.getElementById('credit-hours');
const gradeSelect = document.getElementById('letter-grade');
const courseList = document.getElementById('course-list');
const emptyMessage = document.getElementById('empty-message');
const gpaValue = document.getElementById('gpa-value');

function updateUI() {
  courseList.innerHTML = '';
  if (courses.length === 0) {
    emptyMessage.style.display = 'block';
  } else {
    emptyMessage.style.display = 'none';
    courses.forEach(course => {
      const li = document.createElement('li');
      li.className = 'course-item';

      const nameSpan = document.createElement('span');
      nameSpan.className = 'course-name';
      nameSpan.textContent = course.name;

      const detailsSpan = document.createElement('span');
      detailsSpan.className = 'course-details';
      detailsSpan.textContent = `${course.credits} cr · ${course.grade} (${gradePoints[course.grade].toFixed(1)})`;

      li.appendChild(nameSpan);
      li.appendChild(detailsSpan);
      courseList.appendChild(li);
    });
  }

  const totalCredits = courses.reduce((sum, c) => sum + c.credits, 0);
  const totalPoints = courses.reduce((sum, c) => sum + c.credits * gradePoints[c.grade], 0);
  const gpa = totalCredits > 0 ? totalPoints / totalCredits : 0;
  gpaValue.textContent = gpa.toFixed(2);
}

form.addEventListener('submit', function (e) {
  e.preventDefault();

  const name = nameInput.value.trim();
  const credits = parseFloat(creditsInput.value);
  const grade = gradeSelect.value;

  if (!name || isNaN(credits) || credits <= 0) {
    alert('Please enter a valid course name and positive credit hours.');
    return;
  }

  courses.push({ name, credits, grade });
  updateUI();

  form.reset();
  creditsInput.value = 3;
  nameInput.focus();
});

updateUI();
